    /**
     * @method
     * @name krakenfutures#fetchMarkets
     * @description Fetches the available trading markets from the exchange, Multi-collateral markets are returned as linear markets, but can be settled in multiple currencies
     * @see https://docs.kraken.com/api/docs/futures-api/trading/get-instruments
     * @param {object} [params] exchange specific params
     * @returns An array of market structures
     */
    public java.util.concurrent.CompletableFuture<Object> fetchMarkets(Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object parameters = Helpers.getArg(optionalArgs, 0, new java.util.HashMap<String, Object>() {{}});
            Object response = (this.publicGetInstruments(parameters)).join();
            //
            //    {
            //        "result": "success",
            //        "instruments": [
            //            {
            //                "symbol": "fi_ethusd_180928",
            //                "type": "futures_inverse", // futures_vanilla  // spot index
            //                "underlying": "rr_ethusd",
            //                "lastTradingTime": "2018-09-28T15:00:00.000Z",
            //                "tickSize": 0.1,
            //                "contractSize": 1,
            //                "tradeable": true,
            //                "marginLevels": [
            //                    {
            //                        "contracts":0,
            //                        "initialMargin":0.02,
            //                        "maintenanceMargin":0.01
            //                    },
            //                    {
            //                        "contracts":250000,
            //                        "initialMargin":0.04,
            //                        "maintenanceMargin":0.02
            //                    },
            //                    ...
            //                ],
            //                "isin": "GB00JVMLMP88",
            //                "retailMarginLevels": [
            //                    {
            //                        "contracts": 0,
            //                        "initialMargin": 0.5,
            //                        "maintenanceMargin": 0.25
            //                    }
            //                ],
            //                "tags": [],
            //            },
            //            {
            //                "symbol": "in_xbtusd",
            //                "type": "spot index",
            //                "tradeable":false
            //            }
            //        ]
            //        "serverTime": "2018-07-19T11:32:39.433Z"
            //    }
            //
            Object instruments = this.safeValue(response, "instruments", new java.util.ArrayList<Object>(java.util.Arrays.asList()));
            Object result = new java.util.ArrayList<Object>(java.util.Arrays.asList());
            for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(instruments)); i++)
            {
                Object market = Helpers.GetValue(instruments, i);
                Object id = this.safeString(market, "symbol");
                Object marketType = this.safeString(market, "type");
                Object type = null;
                Object index = (Helpers.isGreaterThanOrEqual(Helpers.getIndexOf(((String)marketType), " index"), 0));
                Object linear = null;
                Object inverse = null;
                Object expiry = null;
                if (!Helpers.isTrue(index))
                {
                    linear = (Helpers.isGreaterThanOrEqual(Helpers.getIndexOf(((String)marketType), "_vanilla"), 0));
                    inverse = !Helpers.isTrue(linear);
                    Object settleTime = this.safeString(market, "lastTradingTime");
                    type = ((Helpers.isTrue((Helpers.isEqual(settleTime, null))))) ? "swap" : "future";
                    expiry = this.parse8601(settleTime);
                } else
                {
                    type = "index";
                }
                Object swap = (Helpers.isEqual(type, "swap"));
                Object future = (Helpers.isEqual(type, "future"));
                Object symbol = id;
                Object split = Helpers.split(((String)id), "_");
                Object splitMarket = this.safeString(split, 1);
                Object baseId = Helpers.slice(((String)splitMarket), 0, Helpers.subtract(((String)((String)splitMarket)).length(), 3));
                Object quoteId = "usd"; // always USD
                Object base = this.safeCurrencyCode(baseId);
                Object quote = this.safeCurrencyCode(quoteId);
                // swap == perpetual
                Object settle = null;
                Object settleId = null;
                Object cvtp = this.safeString(market, "contractValueTradePrecision");
                Object amountPrecision = this.parseNumber(this.integerPrecisionToAmount(cvtp));
                Object pricePrecision = this.safeNumber(market, "tickSize");
                Object contract = (Helpers.isTrue(Helpers.isTrue(swap) || Helpers.isTrue(future)) || Helpers.isTrue(index));
                Object swapOrFutures = (Helpers.isTrue(swap) || Helpers.isTrue(future));
                if (Helpers.isTrue(swapOrFutures))
                {
                    Object exchangeType = this.safeString(market, "type");
                    if (Helpers.isTrue(Helpers.isEqual(exchangeType, "futures_inverse")))
                    {
                        settle = base;
                        settleId = baseId;
                        inverse = true;
                    } else
                    {
                        settle = quote;
                        settleId = quoteId;
                        inverse = false;
                    }
                    linear = !Helpers.isTrue(inverse);
                    symbol = Helpers.add(Helpers.add(Helpers.add(Helpers.add(base, "/"), quote), ":"), settle);
                    if (Helpers.isTrue(future))
                    {
                        symbol = Helpers.add(Helpers.add(symbol, "-"), this.yymmdd(expiry));
                    }
                }
    final Object finalSymbol = symbol;
                final Object finalBase = base;
                final Object finalSettle = settle;
                final Object finalSettleId = settleId;
                final Object finalType = type;
                final Object finalSwap = swap;
                final Object finalLinear = linear;
                final Object finalInverse = inverse;
                final Object finalExpiry = expiry;
                            ((java.util.List<Object>)result).add(new java.util.HashMap<String, Object>() {{
                    put( "id", id );
                    put( "symbol", finalSymbol );
                    put( "base", finalBase );
                    put( "quote", quote );
                    put( "settle", finalSettle );
                    put( "baseId", baseId );
                    put( "quoteId", quoteId );
                    put( "settleId", finalSettleId );
                    put( "type", finalType );
                    put( "spot", false );
                    put( "margin", false );
                    put( "swap", finalSwap );
                    put( "future", future );
                    put( "option", false );
                    put( "index", index );
                    put( "active", Krakenfutures.this.safeBool(market, "tradeable") );
                    put( "contract", contract );
                    put( "linear", finalLinear );
                    put( "inverse", finalInverse );
                    put( "contractSize", Krakenfutures.this.safeNumber(market, "contractSize") );
                    put( "taker", Krakenfutures.this.safeNumber(Helpers.GetValue(Krakenfutures.this.fees, "trading"), "taker") );
                    put( "maker", Krakenfutures.this.safeNumber(Helpers.GetValue(Krakenfutures.this.fees, "trading"), "maker") );
                    put( "maintenanceMarginRate", null );
                    put( "expiry", finalExpiry );
                    put( "expiryDatetime", Krakenfutures.this.iso8601(finalExpiry) );
                    put( "strike", null );
                    put( "optionType", null );
                    put( "precision", new java.util.HashMap<String, Object>() {{
                        put( "amount", amountPrecision );
                        put( "price", pricePrecision );
                    }} );
                    put( "limits", new java.util.HashMap<String, Object>() {{
                        put( "leverage", new java.util.HashMap<String, Object>() {{
                            put( "min", null );
                            put( "max", null );
                        }} );
                        put( "amount", new java.util.HashMap<String, Object>() {{
                            put( "min", null );
                            put( "max", null );
                        }} );
                        put( "price", new java.util.HashMap<String, Object>() {{
                            put( "min", null );
                            put( "max", null );
                        }} );
                        put( "cost", new java.util.HashMap<String, Object>() {{
                            put( "min", null );
                            put( "max", null );
                        }} );
                    }} );
                    put( "created", Krakenfutures.this.parse8601(Krakenfutures.this.safeString(market, "openingDate")) );
                    put( "info", market );
                }});
            }
            Object settlementCurrencies = Helpers.GetValue(Helpers.GetValue(this.options, "settlementCurrencies"), "flex");
            Object currencies = new java.util.ArrayList<Object>(java.util.Arrays.asList());
            for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(settlementCurrencies)); i++)
            {
                Object code = Helpers.GetValue(settlementCurrencies, i);
                ((java.util.List<Object>)currencies).add(new java.util.HashMap<String, Object>() {{
                    put( "id", ((String)code).toLowerCase() );
                    put( "numericId", null );
                    put( "code", code );
                    put( "precision", null );
                }});
            }
            this.currencies = this.mapToSafeMap(this.deepExtend(currencies, this.currencies));
            return result;
        });

    }

